contract InvMutTest {
    C c;
    address deployer;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We need to be owner to call owner-only functions. The test deployer deployed C in the environment,
    // but the checker deploys a fresh C and then passes it to this test's constructor, so this contract
    // is NOT the owner. To become owner we rely on the fact that the test harness deploys C with this
    // contract as msg.sender (per problem statement). So we can call owner-only functions here.

    function run(uint256 newLimit) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= 0);

        // Read bet limit before the owner-only adjustment
        uint256 beforeLimit = c.currentBetLimit(); if (__ESBMC_reverted()) return;
        bool beforeHasWager = c.hasPlayerWagered(address(this)); if (__ESBMC_reverted()) return;

        // Call owner-only AdjustBetAmounts to set new limit
        c.AdjustBetAmounts(newLimit); if (__ESBMC_reverted()) return;

        // Read values after the call
        uint256 afterLimit = c.currentBetLimit(); if (__ESBMC_reverted()) return;
        bool afterHasWager = c.hasPlayerWagered(address(this)); if (__ESBMC_reverted()) return;

        // Assert general rule: after calling AdjustBetAmounts as owner, currentBetLimit equals newLimit,
        // and the call does not itself create a wager for this address (i.e., hasPlayerWagered only true if it was true before).
        assert(afterLimit == newLimit && (afterHasWager == beforeHasWager));
    }

    receive() external payable {}
}

