    PoCGame c;
    address deployer;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 newLimit) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= 0);
        uint256 beforeLimit;
        try c.currentBetLimit() returns (uint256 __r) { beforeLimit = __r; } catch { return; }
        bool beforeHasWager;
        try c.hasPlayerWagered(address(this)) returns (bool __r) { beforeHasWager = __r; } catch { return; }
        try c.AdjustBetAmounts(newLimit) {} catch { return; }
        uint256 afterLimit;
        try c.currentBetLimit() returns (uint256 __r) { afterLimit = __r; } catch { return; }
        bool afterHasWager;
        try c.hasPlayerWagered(address(this)) returns (bool __r) { afterHasWager = __r; } catch { return; }
        assertTrue(afterLimit == newLimit && (afterHasWager == beforeHasWager));
    }

    function testFuzz_run(uint256 newLimit) public {
        _run(newLimit);
    }

    receive() external payable {}
}
